import json,os,pathlib,shlex,subprocess,sys,time
config=json.loads(pathlib.Path('config.json').read_text())
children=[]
try:
 if config.get('mode') != 'invalid':
  for i in range(2):
   ready='ready-'+str(i)
   env=dict(os.environ,FIXTURE_COMM='pds168target',FIXTURE_READY=ready)
   p=subprocess.Popen(['pds168target'],executable='./holder',env=env,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE)
   children.append(p)
   deadline=time.monotonic()+4
   while not pathlib.Path(ready).exists():
    if p.poll() is not None: raise RuntimeError('holder exited early')
    if time.monotonic()>deadline: raise RuntimeError('holder readiness timeout')
    time.sleep(.01)
   assert pathlib.Path('/proc/%d/comm'%p.pid).read_text()=='pds168target\n'
   assert pathlib.Path('/proc/%d/cmdline'%p.pid).read_bytes()==b'pds168target\0'
 args=config['arguments']
 script='pidof '+shlex.join(args)+'; exit $?'
 result=subprocess.run([sys.argv[1],'--noprofile','--norc','-c',script],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=4)
 if config.get('mode') == 'invalid':
  err=result.stderr
  good=err in (b'', b'pidof: invalid options on command line!\n\n')
  if result.returncode != 1 or result.stdout or not good:
   raise AssertionError((result.returncode, result.stdout, result.stderr))
 else:
  pids=[str(p.pid).encode() for p in children]
  sep=config['separator'].encode()
  valid=[pids[0]+sep+pids[1]+b'\n', pids[1]+sep+pids[0]+b'\n']
  if result.returncode != 0 or result.stdout not in valid or result.stderr:
   raise AssertionError((result.returncode, result.stdout, result.stderr, valid))
 print('owned PIDs and separator verified')
finally:
 for p in children:
  if p.poll() is None: p.terminate()
 for p in children:
  try: p.wait(timeout=2)
  except subprocess.TimeoutExpired: p.kill(); p.wait()
  p.stderr.close()

